3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	
6	/**
7	 * Assigns the {@code membershipNumber} formatted {@code <customerCode>-M<YY>}, where
8	 * {@code <customerCode>} is the owner's region-and-hash customer code and YY is the last two digits of
9	 * the fiscal year (starting 1 July) of the business-day-adjusted registration date
10	 * (e.g. a registration on 2026-10-02 falls in the fiscal year ending June 2027, so
11	 * {@code NSW-A1B2C3D4-M27}). Runs after {@link AssignCustomerCode} so the customer code is already
12	 * assigned, and after {@link BuildOwner} which defaults and business-day-adjusts the registration date.
13	 */
14	public class AssignMembershipNumber {
15	
16	    public void service(@Val Owner owner) {
17	        String yy = String.format("%02d", Owner.fiscalYear(owner.getRegistrationDate()) % 100);
18	        owner.setMembershipNumber(String.format("%s-M%s", owner.getCustomerCode(), yy));
19	    }
20	}
