295	    /**
296	     * The ceiling applied to this owner's {@link #getMembershipLevel() membershipLevel}, or {@code null}
297	     * when none applies. Set once at creation to one above the maximum membershipLevel among the owner's
298	     * existing household members (see
299	     * {@link org.springframework.samples.petclinic.rest.function.owner.CapMembershipLevel}); a new owner
300	     * with no existing household member has no cap.
301	     *
302	     * <p>Unlike the other inputs to {@link #getMembershipLevel()} (points and household size), which are
303	     * recomputed on every read, the cap is a deliberate creation-time snapshot: the rule is about the
304	     * household as it stood when this owner joined, so the ceiling is persisted and reapplied on later
305	     * reads rather than re-derived from the household's current membership.
306	     */
307	    public Integer getMembershipLevelCap() {
308	        return this.membershipLevelCap;
309	    }
