329	    /**
330	     * Sets the number of owners that belong to this owner's household (same last name and postcode; see
331	     * {@link org.springframework.samples.petclinic.rest.function.owner.Household}), including this owner.
332	     * Computed per request and used only by {@link #getMembershipPoints()} — a household of three or more
333	     * contributes points. Not persisted and not serialized into the response (no getter is exposed); the
334	     * count is recomputed on each read because household membership changes as owners come and go.
335	     */
336	    public void setHouseholdSize(Integer householdSize) {
337	        this.householdSize = householdSize;
338	    }
