352	    /**
353	     * Whether this response should carry a per-city capacity warning: {@code true} when this owner's city
354	     * already contains between 40 and 49 owners (inclusive), approaching the per-city capacity limit of 50.
355	     * Computed per request, not persisted.
356	     */
357	    public Boolean getCapacityWarning() {
358	        return this.capacityWarning;
359	    }
