365	    /**
366	     * Whether this owner is a <em>possible</em> (soft) duplicate of another owner: {@code true} when some
367	     * other owner has a <em>different</em> {@link #getIdentityKey() identity key} yet shares both this
368	     * owner's last-name {@link #soundex(String) Soundex} and postcode — a near match that is not the same
369	     * identity. Computed per request, not persisted. See {@link #getPossibleDuplicateOf()} for the matched
370	     * owner.
371	     */
372	    public Boolean getPossibleDuplicate() {
373	        return this.possibleDuplicate;
374	    }
375	
376	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
377	        this.possibleDuplicate = possibleDuplicate;
378	    }
