380	    /**
381	     * The id of the existing owner this owner possibly duplicates (same last-name Soundex and postcode, but
382	     * a different identity key), or {@code null} when {@link #getPossibleDuplicate() possibleDuplicate} is
383	     * false. When several owners match, this is the earliest (lowest id). Computed per request, not
384	     * persisted.
385	     */
386	    public Integer getPossibleDuplicateOf() {
387	        return this.possibleDuplicateOf;
388	    }
389	
390	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
391	        this.possibleDuplicateOf = possibleDuplicateOf;
392	    }
393	
394	    /**
395	     * The owner's membership points: start at 0; add 2 when an email is present; add 1 when
396	     * {@code namesakeCount} is 0; add 2 for a household of 3 or more members (see
397	     * {@link #setHouseholdSize(Integer)}); add 3 for a tenure of at least one elapsed fiscal year, i.e.
398	     * the {@code registrationDate} falls in an earlier {@link #fiscalYear(LocalDate) fiscal year} than
399	     * today (fiscal years start 1 July). A newly created owner has zero tenure, so a fresh owner scores
400	     * at most 5 points (2 + 1 + 2).
401	     */
402	    public int getMembershipPoints() {
403	        return membershipPoints(this.householdSize);
404	    }
405	
406	    /** The membership points this owner would score for the given household size; see
407	     * {@link #getMembershipPoints()}. Read-only, so a level can be derived for a hypothetical household
408	     * size without mutating this owner's transient {@link #setHouseholdSize(Integer) householdSize}. */
409	    private int membershipPoints(Integer householdSize) {
410	        int points = 0;
411	        boolean hasEmail = this.email != null && !this.email.isBlank();
412	        if (hasEmail) {
413	            points += 2;
414	        }
415	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
416	        if (unique) {
417	            points += 1;
418	        }
419	        boolean largeHousehold = householdSize != null && householdSize >= 3;
420	        if (largeHousehold) {
421	            points += 2;
422	        }
423	        boolean tenured = this.registrationDate != null
424	            && fiscalYear(LocalDate.now()) - fiscalYear(this.registrationDate) >= 1;
425	        if (tenured) {
426	            points += 3;
427	        }
428	        return points;
429	    }
430	
431	    /**
432	     * The owner's membership level, derived from {@link #getMembershipPoints() membershipPoints}:
433	     * 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more. When a
434	     * {@link #getMembershipLevelCap() membershipLevelCap} applies, the derived level is capped to it, so
435	     * a new owner cannot exceed one above the maximum level among their household members.
436	     */
437	    public int getMembershipLevel() {
438	        return membershipLevelForHouseholdSize(this.householdSize);
439	    }
440	
441	    /**
442	     * This owner's membership level as it would be derived for the given household size — i.e. the value
443	     * this owner's own {@code GET} would report when its household holds {@code householdSize} members —
444	     * after applying any {@link #getMembershipLevelCap() cap}. Read-only: used to size a new household
445	     * member's cap from the existing members' levels without mutating their transient household size.
446	     */
447	    public int membershipLevelForHouseholdSize(Integer householdSize) {
448	        int points = membershipPoints(householdSize);
449	        int level;
450	        if (points <= 1) {
451	            level = 1;
452	        }
453	        else if (points <= 3) {
454	            level = 2;
455	        }
456	        else if (points <= 5) {
457	            level = 3;
458	        }
459	        else {
460	            level = 4;
461	        }
462	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
463	            return this.membershipLevelCap;
464	        }
465	        return level;
466	    }
467	
468	    /**
469	     * Fixed city-to-region table mapping each known city to its canonical region string.
470	     */
471	    private static final Map<String, String> CITY_REGION = Map.of(
472	        "Sydney", "NSW",
473	        "Melbourne", "VIC",
474	        "Brisbane", "QLD");
475	
476	    /**
477	     * Region -> inclusive {low, high} four-digit postcode range: the single canonical home of the
478	     * postcode bands (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), read via
479	     * {@link #postcodeRangeOf(String)} by both locality derivation and the create-time range check.
480	     */
481	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
482	        "NSW", new int[] {2000, 2099},
483	        "VIC", new int[] {3000, 3099},
484	        "QLD", new int[] {4000, 4099});
485	
486	    /**
487	     * Fixed region-to-timezone table mapping each known region to its IANA timezone name
488	     * (NSW -> Australia/Sydney, VIC -> Australia/Melbourne, QLD -> Australia/Brisbane). The single
489	     * source of truth for the timezone derivation read by {@link #getTimezone()}.
490	     */
491	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
492	        "NSW", "Australia/Sydney",
493	        "VIC", "Australia/Melbourne",
494	        "QLD", "Australia/Brisbane");
495	
496	    /**
497	     * The canonical region for {@code city} derived from the fixed city-to-region table
498	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), or {@code "UNKNOWN"} when the
499	     * city is not in the table. The single source of truth for the create-time postcode range check in
500	     * {@link org.springframework.samples.petclinic.rest.function.owner.ValidateOwnerPostcode}.
501	     */
502	    public static String regionOf(String city) {
503	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
504	    }
505	
506	    /**
507	     * The inclusive {low, high} four-digit postcode band for {@code region} (NSW 2000-2099,
508	     * VIC 3000-3099, QLD 4000-4099), or {@code null} when the region has no band. This is the single
509	     * source of truth for the bands, shared by {@link #regionOfPostcode(String) the postcode-to-region
510	     * lookup} (which feeds the customerCode's region, and hence the locality) and the create-time
511	     * postcode range check.
512	     */
513	    public static int[] postcodeRangeOf(String region) {
514	        return REGION_POSTCODES.get(region);
515	    }
516	
517	    /**
518	     * The canonical region whose postcode band contains {@code postcode} (NSW 2000-2099, VIC 3000-3099,
519	     * QLD 4000-4099), or {@code null} when {@code postcode} is absent, not four digits, or in no known
520	     * range.
521	     */
522	    public static String regionOfPostcode(String postcode) {
523	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
524	            return null;
525	        }
526	        int value = Integer.parseInt(postcode);
527	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
528	            int[] range = entry.getValue();
529	            if (value >= range[0] && value <= range[1]) {
530	                return entry.getKey();
531	            }
532	        }
533	        return null;
534	    }
535	
536	    /**
537	     * The owner's locality: the REGION segment of the {@link #getCustomerCode() customerCode}, which is
538	     * the region code derived from the postcode at creation (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099,
539	     * else {@code "UNKNOWN"}). The customer code is the single region-and-hash owner identity, so the
540	     * locality reads straight off it rather than re-deriving the region. {@code "UNKNOWN"} when no
541	     * customer code is assigned.
542	     */
543	    public String getLocality() {
544	        if (this.customerCode == null) {
545	            return "UNKNOWN";
546	        }
547	        int dash = this.customerCode.indexOf('-');
548	        return dash > 0 ? this.customerCode.substring(0, dash) : "UNKNOWN";
549	    }
550	
551	    /**
552	     * The owner's IANA timezone, derived from the {@link #getLocality() locality}/region via the fixed
553	     * region-to-timezone table (NSW -> Australia/Sydney, VIC -> Australia/Melbourne,
554	     * QLD -> Australia/Brisbane), or {@code null} (so the field is absent from the response) when the
555	     * locality maps to no known region.
556	     */
557	    public String getTimezone() {
558	        return REGION_TIMEZONE.get(getLocality());
559	    }
560	
561	    /**
562	     * The owner's segment, formatted {@code "<TIER>_<AREA>"}: TIER is {@code "PREMIUM"} when
563	     * {@link #getMembershipLevel() membershipLevel} is 3 or more, otherwise {@code "STANDARD"}; AREA is
564	     * {@code "METRO"} when the {@link #getLocality() locality} is a known region (NSW, VIC or QLD),
565	     * otherwise {@code "REGIONAL"}. One of {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL},
566	     * {@code STANDARD_METRO} or {@code STANDARD_REGIONAL}. Derived per response.
567	     */
568	    public String getOwnerSegment() {
569	        String tier = getMembershipLevel() >= 3 ? "PREMIUM" : "STANDARD";
570	        String area = REGION_POSTCODES.containsKey(getLocality()) ? "METRO" : "REGIONAL";
571	        return tier + "_" + area;
572	    }
573	
574	    /**
575	     * The single Luhn check digit (0-9) computed over the digits contained in the
576	     * {@link #getCustomerCode() customerCode}: non-digit characters are ignored, each second digit from
577	     * the right is doubled (subtracting 9 when the double exceeds 9), the results are summed, and the
578	     * check digit is {@code (10 - sum % 10) % 10}. {@code 0} when no customer code is assigned.
579	     */
580	    public int getCheckDigit() {
581	        String code = this.customerCode;
582	        if (code == null) {
583	            return 0;
584	        }
585	        int sum = 0;
586	        boolean dbl = true;
587	        for (int i = code.length() - 1; i >= 0; i--) {
588	            char c = code.charAt(i);
589	            if (c < '0' || c > '9') {
590	                continue;
591	            }
592	            int d = c - '0';
593	            if (dbl) {
594	                d *= 2;
595	                if (d > 9) {
596	                    d -= 9;
597	                }
598	            }
599	            sum += d;
600	            dbl = !dbl;
601	        }
602	        return (10 - (sum % 10)) % 10;
603	    }
604	
605	    /**
606	     * The owner's preferred contact channel: {@code "EMAIL"} when an email is present, otherwise
607	     * {@code "PHONE"}.
608	     */
609	    public String getContactPreference() {
610	        boolean hasEmail = this.email != null && !this.email.isBlank();
611	        return hasEmail ? "EMAIL" : "PHONE";
612	    }
613	
614	    /**
615	     * The single canonical definition of an owner's derived identity key: the lower-case SHA-256 hex
616	     * digest (64 hex characters) of {@code normalizedTelephone + "|" + lowerEmail + "|" + soundex(lastName)}.
617	     * The telephone is used as given (it is expected to already be canonical E.164); the email is
618	     * lower-cased here and a null/blank email or telephone contributes an empty component; the last name is
619	     * reduced to its {@link #soundex(String) Soundex} code so near-spellings share a key component. This is
620	     * the only place the key is composed and hashed; the stored-owner {@link #getIdentityKey()} routes
621	     * through here so the format cannot drift. The key is both a descriptive, returned field and the single
622	     * basis for create-time duplicate detection (two owners with an equal identity key are the same
623	     * identity — a 409; see {@code CheckIdentityUnique}).
624	     */
625	    public static String identityKey(String telephone, String email, String lastName) {
626	        String tel = (telephone == null) ? "" : telephone;
627	        String mail = (email == null || email.isBlank()) ? "" : email.toLowerCase(Locale.ROOT);
628	        return Sha256.hex(tel + "|" + mail + "|" + soundex(lastName));
629	    }
630	
631	    /**
632	     * The owner's derived identity key, built from its stored canonical telephone (E.164), email and the
633	     * Soundex of its last name via {@link #identityKey(String, String, String)}. Both a descriptive,
634	     * returned value and the single basis for create-time duplicate detection (see
635	     * {@code CheckIdentityUnique}).
636	     */
637	    public String getIdentityKey() {
638	        return identityKey(this.telephone, this.email, this.getLastName());
639	    }
640	
641	    /**
642	     * The American Soundex code of {@code name}: the upper-cased first letter followed by three digits
643	     * derived from the remaining consonants (vowels and the letters H/W are not coded; adjacent letters
644	     * with the same code, and same-coded letters separated only by H/W, collapse to one; a vowel between
645	     * same-coded letters keeps both). Padded with zeros or truncated to exactly four characters. Empty
646	     * when {@code name} holds no letters (or is {@code null}). Used as the last-name component of the
647	     * {@link #identityKey(String, String, String) identity key} so near-spellings share it.
648	     */
649	    public static String soundex(String name) {
650	        if (name == null) {
651	            return "";
652	        }
653	        String letters = name.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
654	        if (letters.isEmpty()) {
655	            return "";
656	        }
657	        StringBuilder code = new StringBuilder();
658	        code.append(letters.charAt(0));
659	        char previous = soundexDigit(letters.charAt(0));
660	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
661	            char ch = letters.charAt(i);
662	            if (ch == 'H' || ch == 'W') {
663	                continue; // acts as a separator: keep 'previous' so the flanking letters still collapse
664	            }
665	            char digit = soundexDigit(ch);
666	            if (digit != '0' && digit != previous) {
667	                code.append(digit);
668	            }
669	            previous = digit; // a vowel ('0') resets, so same-coded letters it separates are both coded
670	        }
671	        while (code.length() < 4) {
672	            code.append('0');
673	        }
674	        return code.toString();
675	    }
676	
677	    /** The Soundex digit for a single upper-case letter; {@code '0'} for vowels and H/W (not coded). */
678	    private static char soundexDigit(char ch) {
679	        switch (ch) {
680	            case 'B': case 'F': case 'P': case 'V':
681	                return '1';
682	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
683	                return '2';
684	            case 'D': case 'T':
685	                return '3';
686	            case 'L':
687	                return '4';
688	            case 'M': case 'N':
689	                return '5';
690	            case 'R':
691	                return '6';
692	            default:
693	                return '0';
694	        }
695	    }
696	
697	    protected Set<Pet> getPetsInternal() {
698	        if (this.pets == null) {
699	            this.pets = new HashSet<>();
700	        }
701	        return this.pets;
702	    }
703	
704	    protected void setPetsInternal(Set<Pet> pets) {
705	        this.pets = pets;
706	    }
707	
708	    public List<Pet> getPets() {
709	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
710	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
711	        return Collections.unmodifiableList(sortedPets);
712	    }
713	
714	    public void setPets(List<Pet> pets) {
715	        this.pets = new HashSet<>(pets);
716	    }
717	
718	    public void addPet(Pet pet) {
719	        getPetsInternal().add(pet);
720	        pet.setOwner(this);
721	    }
722	
723	    /**
724	     * Return the Pet with the given name, or null if none found for this Owner.
725	     *
726	     * @param name to test
727	     * @return true if pet name is already in use
728	     */
729	    public Pet getPet(String name) {
730	        return getPet(name, false);
731	    }
732	
733	    /**
734	     * Return the Pet with the given name, or null if none found for this Owner.
735	     *
736	     * @param name to test
737	     * @return true if pet name is already in use
738	     */
739	    public Pet getPet(String name, boolean ignoreNew) {
740	        name = name.toLowerCase();
741	        for (Pet pet : getPetsInternal()) {
742	            if (!ignoreNew || !pet.isNew()) {
743	                String compName = pet.getName();
744	                compName = compName.toLowerCase();
745	                if (compName.equals(name)) {
746	                    return pet;
747	                }
748	            }
749	        }
750	        return null;
751	    }
752	
753	    public Pet getPet(Integer petId) {
754	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
755	    }
756	
757	    @Override
758	    public String toString() {
759	        return new ToStringCreator(this)
760	
761	            .append("id", this.getId())
762	            .append("new", this.isNew())
763	            .append("lastName", this.getLastName())
764	            .append("firstName", this.getFirstName())
765	            .append("address", this.address)
766	            .append("city", this.city)
767	            .append("telephone", this.telephone)
768	            .toString();
769	    }
770	}
