193	     * {@link #getLastName() last name} (e.g. {@code "DR Franklin"}), or just the last name when no
194	     * title was supplied. Derived per response, not persisted.
195	     */
196	    public String getSalutation() {
197	        if (this.title == null || this.title.isBlank()) {
