211	    /**
212	     * The fiscal year a {@code date} belongs to, as a four-digit year. The fiscal year starts on 1 July
213	     * and is identified by the calendar year in which it ends: a date on or after 1 July of year
214	     * {@code Y} belongs to the fiscal year ending in {@code Y + 1}, while a date in January to June of
215	     * year {@code Y} belongs to the fiscal year ending in {@code Y}.
216	     */
217	    public static int fiscalYear(LocalDate date) {
218	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
219	    }
220	
221	    /**
222	     * The owner's fiscal year, formatted {@code "FY<YY>"} where YY is the last two digits of the
223	     * {@link #fiscalYear(LocalDate) fiscal year} of the business-day-adjusted
224	     * {@link #getRegistrationDate() registrationDate} (e.g. a registration on 2026-10-02 falls in the
225	     * fiscal year ending June 2027, so {@code "FY27"}). {@code null} when no registration date is
226	     * present. Derived per response.
227	     */
228	    public String getFiscalYear() {
229	        if (this.registrationDate == null) {
230	            return null;
231	        }
232	        return String.format("FY%02d", fiscalYear(this.registrationDate) % 100);
233	    }
234	
235	    public LocalDate getBirthDate() {
236	        return this.birthDate;
237	    }
238	
239	    public void setBirthDate(LocalDate birthDate) {
240	        this.birthDate = birthDate;
241	    }
242	
243	    /**
244	     * The owner's age band, derived from {@link #getBirthDate() birthDate} measured against the
245	     * {@link #getRegistrationDate() registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"}
246	     * when 18 to 64, or {@code "SENIOR"} when 65 or older. {@code null} when no birth date is present
247	     * (so the field is absent from the response) or the registration date is unknown.
248	     */
249	    public String getAgeBand() {
250	        if (this.birthDate == null || this.registrationDate == null) {
251	            return null;
252	        }
253	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
254	        if (age < 18) {
255	            return "MINOR";
256	        }
257	        if (age < 65) {
258	            return "ADULT";
259	        }
260	        return "SENIOR";
261	    }
262	
263	    public String getCustomerCode() {
264	        return this.customerCode;
265	    }
266	
267	    public void setCustomerCode(String customerCode) {
268	        this.customerCode = customerCode;
269	    }
