4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	/**
8	 * Single source of truth for SHA-256 hashing used across owner identity derivations. The one place the
9	 * {@code MessageDigest} lookup, UTF-8 encoding, byte-to-hex conversion and {@code NoSuchAlgorithmException}
10	 * handling live, so every hashed identity (the {@link Owner#identityKey identity key}, the household id and
11	 * the customer-code hash) composes the same digest the same way and cannot drift. Callers take the prefix,
12	 * case or length they need from the full lower-case hex returned by {@link #hex(String)}.
13	 */
14	public final class Sha256 {
15	
16	    private Sha256() {
17	    }
18	
19	    /** The lower-case SHA-256 hex digest (64 characters) of the UTF-8 bytes of {@code value}. */
20	    public static String hex(String value) {
21	        try {
22	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
23	            StringBuilder sb = new StringBuilder(digest.length * 2);
24	            for (byte b : digest) {
25	                sb.append(String.format("%02x", b));
26	            }
27	            return sb.toString();
28	        }
29	        catch (NoSuchAlgorithmException e) {
30	            throw new IllegalStateException("SHA-256 not available", e);
31	        }
32	    }
33	}
